import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("AccountLookup");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (accountId == null || accountId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate accountId is numeric
        if (!accountId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid account ID format");
            return;
        }

        // Default fields if not specified
        if (fields == null || fields.isEmpty()) {
            fields = "account_name, balance";
        }

        // Build query with user-specified column selection
        String query = "SELECT " + fields + " FROM accounts WHERE account_id = " + accountId;

        log.info("Executing lookup: " + query);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout for safety
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch lookup endpoint
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        try {
            JSONObject payload = new JSONObject(body.toString());
            JSONArray ids = payload.getJSONArray("account_ids");
            String fields = payload.optString("fields", "account_name, balance");

            StringBuilder inClause = new StringBuilder();
            for (int i = 0; i < ids.length(); i++) {
                if (i > 0) inClause.append(",");
                int id = ids.getInt(i);  // throws if not int
                inClause.append(id);
            }

            String query = "SELECT " + fields + " FROM accounts WHERE account_id IN (" + inClause + ")";

            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 Statement stmt = conn.createStatement()) {
                stmt.setQueryTimeout(5);
                ResultSet rs = stmt.executeQuery(query);
                JSONArray results = new JSONArray();
                ResultSetMetaData meta = rs.getMetaData();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        row.put(meta.getColumnName(i), rs.getObject(i));
                    }
                    results.put(row);
                }
                resp.setContentType("application/json");
                resp.getWriter().write(results.toString());
            }
        } catch (Exception e) {
            log.warning("Batch lookup failed: " + e.getMessage());
            resp.sendError(500, "Processing error");
        }
    }
}
